import json
from pathlib import Path

# ধাপ ১: হাতে-কলমে ৪-সিনেমার Tie-breaking যাচাই (কোনো lambda/comprehension ছাড়াই!)
toy_counts = {105: 42, 12: 42, 88: 55, 7: 42}

def toy_sort_key(movie_id):
    return (-toy_counts[movie_id], movie_id)

toy_ranked = sorted(toy_counts.keys(), key=toy_sort_key)
assert toy_ranked == [88, 7, 12, 105]
print("Toy deterministic rank:", toy_ranked)

# ধাপ ২: বাস্তব MovieLens Fit Data-র শীর্ষ ৫টি জনপ্রিয় সিনেমা বের করা
lab_path = Path("assets/datasets/movielens/recommendation_lab.json")
lab = json.loads(lab_path.read_text(encoding="utf-8"))

titles = {}
all_movie_ids = []
for row in lab["movies"]:
    movie_id = row[0]
    titles[movie_id] = row[1]
    all_movie_ids.append(movie_id)

counts = {}
for movie_id in all_movie_ids:
    counts[movie_id] = 0

for u, i, r, t in lab["train"]:
    if r >= 4.0:
        counts[i] = counts[i] + 1

def pop_sort_key(movie_id):
    return (-counts[movie_id], movie_id)

order = sorted(all_movie_ids, key=pop_sort_key)

# নিশ্চিত করি ক্রমটি Non-increasing
for j in range(4):
    assert counts[order[j]] >= counts[order[j + 1]]

print("Top-5 Most Popular Fit Movies (r >= 4):")
for rank in range(5):
    mid = order[rank]
    print(f"  #{rank + 1}: movieId={mid:4d} | likes={counts[mid]:3d} | {titles[mid]}")

